AndroidiOS <p>Initialize once (e.g. in your <code>Application</code> class):</p> MyApplication.kt<pre><code>class MyApplication : Application() {
    override fun onCreate() {
        super.onCreate()
        if (BuildConfig.DEBUG) {
            Bark.train(AndroidLogTrainer())
        }
    }
}
</code></pre> <p>Log anywhere:</p> <pre><code>class MainActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        Bark.d("Activity created")
        Bark.i("User logged in: ${user.name}")
        Bark.e("Network error", exception)
    }
}
</code></pre> <p>Initialize once (e.g. in your <code>App</code> entry point):</p> MyApp.swift<pre><code>@main
struct MyApp: App {
    init() {
        #if DEBUG
        Bark.train(trainer: NSLogTrainer())
        Bark.train(trainer: ColoredUnitTestTrainer())
        #else
        Bark.train(trainer: NSLogTrainer(minLevel: .warning))
        #endif
    }

    var body: some Scene {
        WindowGroup { ContentView() }
    }
}
</code></pre> <p>Log anywhere:</p> <pre><code>class UserRepository {
    func saveUser(user: User) {
        Bark.d("Saving user: \(user.name)")
        Bark.i("User saved successfully")
    }
}
</code></pre> <p>Tip</p> <p>Copy <code>ios/BarkExtensions.swift</code> into your app target for the clean <code>Bark.d(...)</code> syntax shown above.</p>

Trainer.kt<pre><code>interface Trainer {
    val pack: Pack      // Categorizes the trainer; controls replacement behavior
    val minLevel: Level   // Minimum level this trainer will handle

    fun handle(level: Level, tag: String, message: String, throwable: Throwable?)
}
</code></pre>

CrashReportingTrainer.kt<pre><code>class CrashReportingTrainer(
    override val minLevel: Level = Level.ERROR,
) : Trainer {
    override val pack: Pack = Pack.CUSTOM

    override fun handle(level: Level, tag: String, message: String, throwable: Throwable?) {
        ErrorTracker.log(level, tag, message, throwable)
    }
}
</code></pre>

SlackTrainer.kt<pre><code>class SlackTrainer(
    override val minLevel: Level = Level.WARNING,
    private val webhookUrl: String,
) : Trainer {
    override val pack: Pack = Pack.CUSTOM

    override fun handle(level: Level, tag: String, message: String, throwable: Throwable?) {
        SlackClient.send(webhookUrl, "[${level.name}] $tag: $message")
    }
}
</code></pre>

FileTrainer.kt<pre><code>class FileTrainer(
    override val minLevel: Level = Level.WARNING,
    private val logFile: File,
) : Trainer {
    override val pack: Pack = Pack.FILE

    override fun handle(level: Level, tag: String, message: String, throwable: Throwable?) {
        logFile.appendText("${level.name} [$tag]: $message\n")
        throwable?.let { logFile.appendText(it.stackTraceToString() + "\n") }
    }
}
</code></pre>

ExampleTest.kt<pre><code>class ExampleTest {

    @Before
    fun setup() {
        Bark.releaseAllTrainers()
        Bark.train(ColoredUnitTestTrainer())
    }

    @After
    fun teardown() {
        Bark.releaseAllTrainers()
    }

    @Test
    fun testSomething() {
        Bark.d("Starting test")
        // ...
        Bark.i("Test completed")
    }
}
</code></pre>

